      sequence: Q('Đặt các bước khôi phục SSH theo thứ tự an toàn.', 'Giữ bằng chứng ban đầu, điều tra rồi mới thay đổi dịch vụ có phép; xác minh phải gồm đường kết nối từ client.', { status: ['Ghi trạng thái sshd và listener hiện tại.', 'Quan sát trước giúp biết trạng thái ban đầu và tránh làm mất dấu vết.'], logs: ['Đọc log và kiểm tra cấu hình SSH.', 'Sau khi xác nhận dịch vụ dừng, tìm lỗi có thể khiến nó không khởi động.'], approve: ['Xin phép và đề xuất start nếu điều kiện cho phép.', 'Thay đổi chỉ nên diễn ra khi có quyền và cấu hình phù hợp.'], verify: ['Thử listener và đăng nhập SSH từ client.', 'Service chạy là một phần; kết nối và xác thực của khách mới xác minh chức năng.'] }),
