      output: Q('wa76% và đọc/ghi vda chờ khoảng180ms hỗ trợ nhận định nào?', 'Các dấu hiệu phù hợp I/O chậm; cần tìm tải gây I/O và so host/health, không xác định ổ vật lý hỏng.', {supported:['Điều tra workload I/O và storage/host.','vmstat và iostat cùng chỉ chờ/độ trễ cao trong mẫu.'],over:['Đã chứng minh đĩa vật lý bị hỏng.','Chưa có health/error telemetry hoặc mapping thiết bị vật lý.'],ignore:['CPU user thấp nên await cao không ảnh hưởng ứng dụng.','Task chờ I/O có thể tăng độ trễ trong khi CPU user vẫn thấp.']}),
      evidence: Q('Chọn các số đo trong vmstat và iostat của khoảng chậm.', 'Số đo thời gian chờ là bằng chứng hiệu năng, không phải kết quả chẩn đoán phần cứng.', {p1:['Dòng interval vmstat có wa76%.','Đúng cột wa ở hai mẫu sau dòng đầu.'],p2:['vda có r_await/w_await180ms và %util99 trong interval.','Các cột riêng đọc/ghi của iostat cho số đo này.'],over:['Đã nhận kết quả ổ vật lý hỏng.','Không có SMART/hosterror hoặc kiểm tra vật lý trong hai output.']}),
      decision: Q('Nên làm gì trước khi thay dữ liệu hay yêu cầu đổi storage?', 'Cần tìm nguồn I/O và bằng chứng hạ tầng theo cùng thời gian; xóa dữ liệu không phải chẩn đoán hiệu năng.', {safe:['Tìm process I/O, đối chiếu baseline/host và escalation nếu cần.','Giúp phân biệt workload guest với contention hoặc lỗi lớp storage.'],unsafe:['Xóa dữ liệu ứng dụng để giảm I/O ngay.','Có thể mất dữ liệu và chưa biết process nào tạo tải.'],close:['Đóng ticket vì CPU user còn thấp.','Bằng chứng wa/độ trễ và triệu chứng khách vẫn chưa được xử lý.']}),
